<script>import {login} from '../api/authApi.js';import {authStore} from '../states/authStore.js';import {router} from '../../../router.js';let email=$state('');let password=$state('');let error=$state('');let busy=$state(false);async function submit(e){e.preventDefault();error='';busy=true;try{const data=await login(email.trim(),password);const token=data.token||data.access_token||data.accessToken;if(!token)throw new Error('Token login tidak ditemukan pada respons API.');authStore.setSession(token,data.user||data.profile||null);router.navigate('/');}catch(err){error=err.message||'Login gagal. Periksa email dan kata sandi.';}finally{busy=false;}}</script>
<svelte:head><title>Masuk · Delcom Link Tree</title><meta name="description" content="Masuk untuk mengelola koleksi tautan Delcom Link Tree."/></svelte:head><div class="auth-icon">↗</div><p class="eyebrow">SELAMAT DATANG KEMBALI</p><h1>Masuk ke akunmu</h1><p class="muted">Kelola semua tautan pentingmu di satu tempat.</p><form class="form-stack auth-form" onsubmit={submit}><label for="login-email-input">Email</label><input id="login-email-input" name="email" type="email" autocomplete="username" bind:value={email} required placeholder="nama@email.com"/><label for="login-password-input">Kata sandi</label><input id="login-password-input" name="password" type="password" autocomplete="current-password" bind:value={password} required placeholder="Masukkan kata sandi"/>{#if error}<p class="error" role="alert">{error}</p>{/if}<button id="login-submit-button" class="btn btn-primary btn-full" disabled={busy}>{busy?'Memproses…':'Masuk'}</button></form><p class="auth-switch">Belum punya akun? <a href="/auth/register" onclick={(e)=>{e.preventDefault();router.navigate('/auth/register')}}>Daftar sekarang</a></p>
